def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    recent_opp_def = 0
    for i, (me, opp) in enumerate(history):
        if opp == 'D':
            opp_def += 1
            if i >= n - 5:
                recent_opp_def += 1
    opp_coop = n - opp_def
    opp_coop_rate = opp_coop / n

    if n == 98:
        if opp_def == 0:
            return 'D'
        ret = 0
        tot = 0
        for i in range(n - 1):
            me_i, opp_i = history[i]
            if me_i == 'D' and opp_i == 'C':
                tot += 1
                if history[i+1][1] == 'D':
                    ret += 1
        if opp_coop_rate > 0.5 and tot > 0 and (ret / tot) > 0.5:
            return 'C'
        return 'D'

    if opp_def == 0 and n >= 5:
        return 'D'

    last_me, last_opp = history[-1]

    if n >= 4:
        h1 = history[-1]
        h2 = history[-2]
        if h1[0] != h1[1] and h2[0] != h2[1] and h1[0] != h2[0]:
            return 'C'

    if last_opp == 'C':
        return 'C'
    else:
        if last_me == 'C':
            return 'D'
        else:
            if opp_coop_rate > 0.5 and recent_opp_def <= 1:
                return 'C'
            else:
                return 'D'
